<script setup lang="ts">
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useApp } from '../stores/app'
import type { Post } from '../lib/types'
import { categories } from '../lib/types'
import { dateLabel } from '../lib/format'
import Icon from '../components/Icon.vue'
import Detail from '../components/Detail.vue'
import BriefFeed from '../components/BriefFeed.vue'
import SpeechPlayer from '../components/SpeechPlayer.vue'
const app=useApp(),route=useRoute(),router=useRouter(),index=ref(0),view=ref(route.params.id||app.demo?'精选':'推荐'),category=ref('全部'),detail=ref(false),detailTab=ref<'article'|'notes'>('article'),cover=ref(''),transition=ref(false)
const list=computed(()=>{let rows=app.published;if(view.value==='关注')rows=rows.filter(p=>app.follows.some(f=>f.kind==='category'?f.value===p.category:f.kind==='source'?f.value===p.source_name:`${p.title} ${p.short_summary} ${p.tags.join(' ')}`.toLocaleLowerCase().includes(f.value.toLocaleLowerCase())));if(category.value!=='全部')rows=rows.filter(p=>p.category===category.value);if(view.value==='热点')return [...rows].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||(b.published_at||'').localeCompare(a.published_at||''));return rows})
const current=computed(()=>list.value[index.value]),following=computed(()=>current.value&&app.follows.some(f=>f.kind==='source'&&f.value===current.value!.source_name))
let generation=0, preloadTimer:ReturnType<typeof setTimeout>,lockUntil=0,touchY=0,touchX=0
async function loadCover(post:Post|undefined){const n=++generation;cover.value='';if(!post)return;try{const url=await app.imageFor(post);if(n===generation)cover.value=url}catch(e){app.notify(app.errorMessage(e))}clearTimeout(preloadTimer);preloadTimer=setTimeout(async()=>{const next=list.value[index.value+1];if(next){try{const img=new Image();img.src=await app.imageFor(next)}catch{}}},500)}
watch(current,p=>{loadCover(p);if(p)app.markRead(p.id)}, {immediate:true})
watch([view,category],()=>index.value=0)
watch(()=>route.params.id,id=>{if(id){view.value='精选';const i=list.value.findIndex(p=>p.id===id);if(i>=0){index.value=i;detail.value=true}else app.notify('内容不存在，或尚未发布')}else detail.value=false},{immediate:true})
function move(direction:number){if((view.value==='推荐'&&!app.demo)||detail.value||Date.now()<lockUntil)return;const next=index.value+direction;if(next<0||next>=list.value.length)return;lockUntil=Date.now()+650;transition.value=true;index.value=next;setTimeout(()=>transition.value=false,250)}
function open(tab:'article'|'notes'='article'){detailTab.value=tab;detail.value=true;if(current.value)router.replace(`/post/${current.value.id}`)}
function close(){detail.value=false;if(route.params.id)router.replace('/')}
let wheelSum=0,wheelGesture=false,wheelTimer:ReturnType<typeof setTimeout>
function wheel(e:WheelEvent){if(detail.value||e.ctrlKey)return;e.preventDefault();clearTimeout(wheelTimer);wheelTimer=setTimeout(()=>{wheelSum=0;wheelGesture=false},180);if(wheelGesture||Date.now()<lockUntil)return;wheelSum+=e.deltaY;if(Math.abs(wheelSum)>65){wheelGesture=true;move(wheelSum>0?1:-1);wheelSum=0}}
function touchStart(e:TouchEvent){touchY=e.changedTouches[0]!.clientY;touchX=e.changedTouches[0]!.clientX}
function touchEnd(e:TouchEvent){const y=touchY-e.changedTouches[0]!.clientY,x=touchX-e.changedTouches[0]!.clientX;if(Math.abs(y)>60&&Math.abs(y)>Math.abs(x)*1.3)move(y>0?1:-1)}
function key(e:KeyboardEvent){if((view.value==='推荐'&&!app.demo)||detail.value||['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement).tagName))return;if(e.key==='ArrowDown'){e.preventDefault();move(1)}if(e.key==='ArrowUp'){e.preventDefault();move(-1)}}
async function interaction(kind:'likes'|'bookmarks'){if(current.value)try{await app.toggleInteraction(kind,current.value.id)}catch{}}
async function follow(){if(current.value)try{await app.toggleFollow('source',current.value.source_name)}catch{}}
async function share(){if(!current.value)return;const url=`${location.origin}${location.pathname}#/post/${current.value.id}`;try{await navigator.clipboard.writeText(url);app.notify('链接已复制 · 私人内容仅所有者可访问')}catch{app.notify(`请复制地址栏中的文章链接`)}}
onMounted(()=>document.addEventListener('keydown',key));onUnmounted(()=>{document.removeEventListener('keydown',key);clearTimeout(preloadTimer);clearTimeout(wheelTimer)})
</script>
<template><div class="feed-page"><section class="feed-main"><div class="feed-heading"><div class="feed-tabs"><button v-for="tab in ['推荐','精选','关注','热点','分类']" :key="tab" :class="{active:view===tab}" @click="view=tab">{{tab}}<span v-if="tab==='推荐'" class="tab-dot"></span></button></div><span class="edition-label">{{view==='推荐'&&!app.demo?'LIVE SOURCES':'THE DAILY EDIT'}} <span> / </span> {{view==='推荐'&&!app.demo?'每小时更新':String(list.length).padStart(2,'0')+' STORIES'}}</span></div><div v-if="view==='分类'" class="feed-category"><button v-for="c in ['全部',...categories]" :key="c" :class="['filter-chip',{active:category===c}]" @click="category=c">{{c}}</button></div><BriefFeed v-if="view==='推荐'&&!app.demo"/><div v-else-if="current" class="story-stage" @wheel="wheel" @touchstart="touchStart" @touchend="touchEnd"><article class="hero-story" :class="{changing:transition}"><img v-if="cover" :src="cover" class="story-cover" :alt="current.image_attribution"/><div v-else class="story-cover no-cover"><Icon name="Layers3" :size="120"/></div><div class="story-shade"></div><div class="story-top"><span class="selected-label"><span></span>{{current.origin==='demo'?'精选体验':'今日精选'}}</span><span class="story-count">{{String(index+1).padStart(2,'0')}} <span>/ {{String(list.length).padStart(2,'0')}}</span></span></div><span class="art-caption">{{current.origin==='demo'?'ORIGINAL CONCEPT ART':!current.image_path?'原创分类示意图 · 非新闻现场':current.is_ai_generated_image?'AI 生成示意图':'新闻配图'}}<span>↗</span></span><div class="story-content"><div class="story-meta"><span class="category-tag">{{current.category}}</span><span v-for="tag in current.tags.filter(t=>t!=='演示').slice(0,2)" :key="tag" class="story-tag"># {{tag}}</span><span class="read-time"><Icon name="Clock3" :size="13"/>3 分钟阅读</span></div><h1>{{current.title}}</h1><p class="story-summary">{{current.short_summary}}</p><SpeechPlayer v-if="!detail" :key="current.id" compact :title="current.title" :text="current.short_summary"/><div class="story-bottom"><div class="story-source"><span class="source-avatar">T<span>✳</span></span><span>{{current.source_name}}<small>{{current.origin==='demo'?'演示内容 · 非真实报道':dateLabel(current.source_published_at)}}</small></span><button class="follow-btn" :aria-label="following?'取消关注来源':'关注来源'" @click="follow"><Icon :name="following?'Check':'Plus'" :size="14"/>{{following?'已关注':'关注'}}</button></div><button class="read-button" @click="open()">展开全文<Icon name="ArrowUpRight" :size="17"/></button></div></div><div class="story-actions"><button :class="{selected:app.likes.includes(current.id)}" aria-label="点赞" :aria-pressed="app.likes.includes(current.id)" @click="interaction('likes')"><span><Icon name="Heart" :size="23"/></span><small>{{app.likes.includes(current.id)?'已喜欢':'喜欢'}}</small></button><button :class="{selected:app.bookmarks.includes(current.id)}" aria-label="收藏新闻" :aria-pressed="app.bookmarks.includes(current.id)" @click="interaction('bookmarks')"><span><Icon name="Bookmark" :size="22"/></span><small>{{app.bookmarks.includes(current.id)?'已收藏':'收藏'}}</small></button><button aria-label="私人笔记" @click="open('notes')"><span><Icon name="MessageCircle" :size="22"/></span><small>{{app.notes.filter(n=>n.post_id===current.id).length||'笔记'}}</small></button><button aria-label="分享新闻" @click="share"><span><Icon name="Share2" :size="21"/></span><small>分享</small></button></div></article><div class="feed-control"><div class="swipe-hint"><Icon name="ArrowUp" :size="14"/><Icon name="ArrowDown" :size="14"/><span>上下滑动，遇见新知</span><kbd>↑</kbd><kbd>↓</kbd></div><div class="story-progress"><span v-for="(_,i) in list" :key="i" :class="{active:index===i,read:i<index}" @click="index=i" :aria-label="`第 ${i+1} 条`" role="button" tabindex="0" @keydown.enter="index=i"></span></div><div class="direction-buttons"><button class="icon-btn" aria-label="上一条新闻" :disabled="index===0" @click="move(-1)"><Icon name="ArrowUp" :size="17"/></button><button class="icon-btn" aria-label="下一条新闻" :disabled="index===list.length-1" @click="move(1)"><Icon name="ArrowDown" :size="17"/></button></div></div></div><div v-else class="empty-state"><Icon :name="view==='关注'?'Rss':'Layers3'" :size="42"/><h2>{{view==='关注'?'关注你感兴趣的世界':'今天的好内容，正在路上'}}</h2><p>{{view==='关注'?'在发现页关注分类，或在卡片中关注新闻来源。':'连接信息源、审核并发布后，新闻会在这里出现。'}}</p><RouterLink :to="view==='关注'?'/discover':'/admin'" class="btn primary">{{view==='关注'?'去发现':'前往管理后台'}}<Icon name="ArrowRight" :size="17"/></RouterLink></div></section><aside class="daily-sidebar"><div class="daily-heading"><span class="eyebrow">YOUR DAILY BRIEF</span><Icon name="Sparkles" :size="17"/></div><h2>早安，保持好奇<span>。</span></h2><p class="brief-intro">从科技到人文，<br>在信息洪流里，找到你的坐标。</p><div class="edition-stats"><div><strong>{{String(app.published.length).padStart(2,'0')}}<span>条</span></strong><small>{{app.demo?'演示精选':'可读内容'}}</small></div><span class="stat-line"></span><div><strong>08<span>:00</span></strong><small>每日一次 · {{app.settings.timezone==='Asia/Tokyo'?'东京时间':'北京时间'}}</small></div></div><div class="thin-rule"></div><div class="aside-title"><h3>下一站，新视野</h3><span>UP NEXT</span></div><button v-for="p in list.slice(index+1,index+4)" :key="p.id" class="up-next" @click="index=list.indexOf(p)"><img v-if="app.demo&&p.image_url" :src="p.image_url" alt="原创概念插画"/><span v-else class="thumb-fallback"><Icon name="Layers3" :size="23"/></span><span><small>{{p.category}}<span> / {{p.tags[0]}}</span></small><strong>{{p.title}}</strong></span><Icon name="ChevronRight" :size="14"/></button><p v-if="index>=list.length-1&&list.length" class="end-copy">已经读到最后。<br>给好奇心一点消化的时间。</p><div class="thin-rule"></div><div class="aside-title"><h3>探索兴趣</h3><RouterLink to="/discover" aria-label="查看全部分类"><Icon name="ArrowUpRight" :size="15"/></RouterLink></div><div class="interest-chips"><RouterLink v-for="(c,i) in categories" :key="c" :to="{path:'/discover',query:{category:c}}"><span :style="{'--chip-color':['#85b9c5','#f3a778','#d1d690','#a4b9df','#c6b4db','#d4abbd'][i]}"></span>{{c}}<Icon name="ArrowUpRight" :size="12"/></RouterLink></div><div class="reading-card"><div><Icon name="CheckCheck" :size="17"/><span>今日阅读足迹</span><small>{{app.read.filter(id=>app.published.some(p=>p.id===id)).length}} / {{app.published.length}}</small></div><div class="reading-track"><span :style="{width:`${app.published.length?app.read.filter(id=>app.published.some(p=>p.id===id)).length/app.published.length*100:0}%`}"></span></div><p>不必读完所有，读到喜欢就好。</p></div><div class="aside-footer"><Icon name="ShieldCheck" :size="13"/>{{app.demo?'演示数据 · 自有原创插画':'私人空间 · 所有内容仅你可见'}}</div></aside><Detail v-if="detail&&current" :key="current.id" :post="current" :tab="detailTab" @close="close"/></div></template>
